/**
 * Represents a rotation structure with pitch and yaw
 * components.
 */
export class XYRotation {
    /**
     * Yaw component (left-to-right) of this position.
     */
    "x": number;
    /**
     * Pitch (up-and-down) element of this rotation.
     */
    "y": number;
    protected constructor();
}
